// i18n bootstrap — initialise once; import this module at the app root before
// rendering. All components use the `useTranslation` hook from react-i18next.
//
// Day-1 languages: EN (complete), HI (complete), TE (complete).
// Language choice is persisted to localStorage via the detector below.
// Proper nouns (AntHire, Google Gemini, Groq, Sarvam, LiveKit, DPDP) stay
// as-is across all locales — they are not translatable brand names.
//
// NOTE: HI/TE translations are a first-pass for UI coverage.
// They must receive native-speaker and (for ConsentModal) legal review
// before a production/government-bid launch.
//
// ERASURE AND CONSENT KEYS CARRY A HIGHER BAR THAN GENERAL UI COPY.
// A mistranslated button label is an annoyance; a mistranslated IRREVERSIBLE
// DELETE is a data principal destroying their own application because the copy
// read as something softer. The blanket caveat above is a whole-bundle,
// pre-launch ask - too slow and too coarse for these. `resumeApply.delete*`,
// `resumeApply.keepIt`, `resumeApply.deletedDesc`, the ConsentModal keys,
// `apply.rediscoveryConsent`, every `rediscovery.*` key (PH5-E3 — the
// rediscovery opt-in is a DPDP §6(1) consent in its own right, separate from
// the application consent above it), and every `publicExam.camera*` key
// (camera-proctoring contract §3/§8 — the exam's dedicated, never-bundled
// camera-proctoring consent step: a mistranslation here could read as video
// being recorded when it structurally never is, or as declining being
// impossible when the round doesn't require the camera at all) want a
// targeted native-speaker pass, and want it BEFORE they are candidate-facing
// rather than before launch. HI/TE for these ship UNREVIEWED with this
// change — that is stated, not designed away.
//
// Acted on once already: te.resumeApply.deleteDesc rendered "cannot be undone"
// with a verb reading primarily as "cannot be CANCELLED" - a weaker claim than
// the English and Hindi, on the one control that cannot be taken back. NOTE the
// same verb is still used by an unrelated pre-existing te key; that one is out
// of this change's scope and is worth checking in the targeted pass.
import i18n from 'i18next';
import { initReactI18next } from 'react-i18next';

// ── Persistence key ───────────────────────────────────────────────────────────
const LANG_STORAGE_KEY = 'intants:ui-language';

const SUPPORTED = new Set(['en', 'hi', 'te']);

function getStoredLang(): string {
  try {
    const v = localStorage.getItem(LANG_STORAGE_KEY);
    return v && SUPPORTED.has(v) ? v : 'en';
  } catch {
    return 'en';
  }
}

